MonarchSectionCard(title = {{heading}}, tone = MonarchTone.Danger) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
        MonarchText(text = {{title}}, style = MonarchTextStyle.BodyStrong, heading = true)
        MonarchText(
            text = {{description}},
            style = MonarchTextStyle.Caption,
            color = MonarchTheme.colors.textMuted,
        )
        MonarchButton(
            text = {{action}},
            onClick = { if (isLastOwner) blocked = true else confirming = true },
            variant = MonarchButtonVariant.Danger,
        )
    }
}
if (blocked) {
    MonarchDialog(
        onDismissRequest = { blocked = false },
        title = "You can’t leave yet",
        description = "You are the only owner. Transfer ownership to another member before you leave.",
        actions = {
            MonarchButton(text = "Close", onClick = { blocked = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(
                text = "Transfer ownership",
                onClick = {
                    blocked = false
                    // Open the app's transfer ownership screen here.
                },
                variant = MonarchButtonVariant.Primary,
            )
        },
    )
}
if (confirming) {
    MonarchBottomSheet(
        onDismissRequest = { confirming = false },
        title = "Leave " + {{workspaceName}} + "?",
        description = "You are removed from the workspace straight away.",
        dismissible = !leaving,
    ) {
        val sheet = this
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchConsequenceList(
                items = listOf(
                    MonarchConsequence(MonarchConsequenceKind.Removed, "You lose access to " + apps.joinToString(", ")),
                    MonarchConsequence(
                        MonarchConsequenceKind.Kept,
                        "What you created stays in the workspace for the other members",
                    ),
                    MonarchConsequence(MonarchConsequenceKind.Warning, "You need a new invite to come back"),
                ),
            )
            failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
            MonarchButton(
                text = "Leave workspace",
                onClick = {
                    leaving = true
                    failure = null
                    scope.launch {
                        // The app removes the membership on its server here.
                        // On failure: failure = "Couldn’t leave the workspace. Try again."
                        leaving = false
                        sheet.dismiss()
                        // Then navigate away from the workspace.
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Danger,
                loading = leaving,
            )
            MonarchButton(
                text = "Cancel",
                onClick = { confirming = false },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Ghost,
                enabled = !leaving,
            )
        }
    }
}

